command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="ce51aa2804902990776071293990dad48a4ed1f1"
$candidate="24bb8722c06b302f6a6b9c00aad34293a38be0d0"
$branch="work/search-content-regex-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "final docs FAST fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before final docs FAST"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "final docs candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("fly-content-regex-docs-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "final docs worktree add failed"}
  Set-Location -LiteralPath $temp
  & git diff --check ($main+"..."+$candidate)
  if($LASTEXITCODE -ne 0){throw "final docs diff check failed"}
  & python -X utf8 tools\winui\run_checks.py fast --before $main --head $candidate
  if($LASTEXITCODE -ne 0){throw "final docs FAST failed"}
  Write-Host "CONTENT_REGEX_DOCS_DIFF_CHECK=PASS"
  Write-Host "CONTENT_REGEX_DOCS_FAST=PASS"
  Write-Host "CONTENT_REGEX_REUSED_PRODUCT_VALIDATION_RUN=37549985817"
  Write-Host "CONTENT_REGEX_REUSED_NATIVE_DEBUG_RUN=37547158373"
  Write-Host "CONTENT_REGEX_REUSED_NATIVE_RELEASE_RUN=37547329626"
}finally{
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
